window.kbPageData["views/entry/k-8c06c72575da4818"] = {"key":"entry/k-8c06c72575da4818","state":{"route":"entry/k-8c06c72575da4818"},"node":{"id":"k-8c06c72575da4818","mode":"k","title":"两种溶液混合的质量比","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["两种溶液混合时质量与各自和混合浓度的差值成反比"],"qs":["江苏 2023 A类 行测#62"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两种浓度不同的溶液混合时，若溶质和溶液的质量均守恒，混合浓度就是两种原溶液浓度按质量加权的平均值。两种原溶液的质量之比，等于它们各自与混合浓度之差的绝对值的反比。","review":{"definition":"两种浓度不同的溶液混合时，若溶质和溶液的质量均守恒，混合浓度就是两种原溶液浓度按质量加权的平均值。两种原溶液的质量之比，等于它们各自与混合浓度之差的绝对值的反比。","explanation":"低浓度溶液相对混合浓度少含的溶质质量，恰好等于高浓度溶液相对混合浓度多含的溶质质量，所以两侧的质量与浓度差的乘积相等。本题先把72%和78%的溶液视为一份76%的溶液。68%与76%的溶液混成74%，质量比为(76－74)∶(74－68)＝1∶3，因此76%的混合液有180克。再按(78－76)∶(76－72)＝1∶2分配这180克，得72%的溶液有60克，选D。","references":[],"evidence":"浓度之差与酒精溶液质量成反比","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#62":{"paper":"江苏 2023 A类 行测","n":62,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",11],"asrc":["be17f9afe070cf13a0fb.pdf",18],"card":"6408dd8d57052de0c314f833","links":[{"id":"k-8c06c72575da4818","role":"解题依据","why":"由溶质质量守恒可确定两种组分的质量比，题中两次混合均用到这一关系。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-8c06c72575da4818":[["江苏 2023 A类 行测#62"]]}};
